🚀 The feature, motivation and pitch
Hello!
Currently, the CalculateSmallVectorDefaultInlinedElements functionality is implemented using a template struct. With PyTorch now supporting C++17, it is possible to migrate this code to a constexpr function.
By reducing template instantiation complexity, the constexpr function minimizes compilation time and the size of the generated binary, as it avoids generating multiple instances of the same logic for different template parameters.
The current implementation:
// c10/util/SmallVector.h
/// Helper class for calculating the default number of inline elements for
/// `SmallVector<T>`.
///
/// This should be migrated to a constexpr function when our minimum
/// compiler support is enough for multi-statement constexpr functions.
template <typename T>
struct CalculateSmallVectorDefaultInlinedElements {
  static constexpr size_t kPreferredSmallVectorSizeof = 64;
  static_assert(
      sizeof(T) <= 256,
      "You are trying to use a default number of inlined elements for "
      "`SmallVector<T>` but `sizeof(T)` is really big! Please use an "
      "explicit number of inlined elements with `SmallVector<T, N>` to make "
      "sure you really want that much inline storage.");

  static constexpr size_t PreferredInlineBytes =
      kPreferredSmallVectorSizeof - sizeof(SmallVector<T, 0>);
  static constexpr size_t NumElementsThatFit = PreferredInlineBytes / sizeof(T);
  static constexpr size_t value =
      NumElementsThatFit == 0 ? 1 : NumElementsThatFit;
};
Alternatives
Migrate the calculation logic to a constexpr function
template <typename T>
constexpr size_t CalculateSmallVectorDefaultInlinedElements() {
  constexpr size_t kPreferredSmallVectorSizeof = 64;
  static_assert(
      sizeof(T) <= 256,
      "You are trying to use a default number of inlined elements for "
      "`SmallVector<T>` but `sizeof(T)` is really big! Please use an "
      "explicit number of inlined elements with `SmallVector<T, N>` to make "
      "sure you really want that much inline storage.");

  constexpr size_t PreferredInlineBytes =
      kPreferredSmallVectorSizeof - sizeof(SmallVector<T, 0>);
  constexpr size_t NumElementsThatFit = PreferredInlineBytes / sizeof(T);
  return NumElementsThatFit == 0 ? 1 : NumElementsThatFit;
}

// Implementation of SmallVector template class
template <typename T, unsigned N = CalculateSmallVectorDefaultInlinedElements<T>()>
class SmallVector {
public:
    // SmallVector implementation...
};
